-- 1. Visitors table (IP + UUID Anonymous tracking like tawk.to)
CREATE TABLE IF NOT EXISTS `visitors` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `visitor_uuid` VARCHAR(100) NOT NULL UNIQUE,
  `ip_address` VARCHAR(50) DEFAULT '127.0.0.1',
  `user_agent` TEXT,
  `country` VARCHAR(100) DEFAULT 'Unknown',
  `city` VARCHAR(100) DEFAULT 'Unknown',
  `current_page` VARCHAR(255) DEFAULT '/',
  `is_online` INT DEFAULT 1,
  `mode` VARCHAR(20) DEFAULT 'bot', -- 'bot' (AI) or 'live' (Agent takeover)
  `last_seen_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_visitor_uuid` (`visitor_uuid`),
  INDEX `idx_last_seen` (`last_seen_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Messages table (Visitor, Bot & Live Agent conversation history)
CREATE TABLE IF NOT EXISTS `messages` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `visitor_uuid` VARCHAR(100) NOT NULL,
  `sender` VARCHAR(20) NOT NULL, -- 'visitor', 'bot', 'agent', 'system'
  `message` MEDIUMTEXT NOT NULL,
  `metadata` LONGTEXT DEFAULT NULL, -- JSON citations, scores, fallback flags
  `is_read` INT DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_msg_visitor` (`visitor_uuid`),
  INDEX `idx_msg_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Knowledge chunks for RAG & Vector Semantic Search
CREATE TABLE IF NOT EXISTS `knowledge_chunks` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(255) NOT NULL,
  `content` MEDIUMTEXT NOT NULL,
  `category` VARCHAR(100) DEFAULT 'General',
  `url` VARCHAR(500) DEFAULT '',
  `embedding` LONGTEXT DEFAULT NULL, -- JSON float array of vector embeddings
  `chunk_type` VARCHAR(50) DEFAULT 'faq', -- 'faq', 'scraped', 'custom'
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_chunk_category` (`category`),
  INDEX `idx_chunk_type` (`chunk_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. Captured VIP Concierge Leads & Fallback Contact Requests
CREATE TABLE IF NOT EXISTS `leads` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `visitor_uuid` VARCHAR(100) NOT NULL,
  `name` VARCHAR(150) NOT NULL,
  `email` VARCHAR(150) DEFAULT NULL,
  `phone` VARCHAR(50) DEFAULT NULL,
  `category` VARCHAR(100) DEFAULT 'Luxury Concierge',
  `note` MEDIUMTEXT DEFAULT NULL,
  `status` VARCHAR(30) DEFAULT 'new', -- 'new', 'contacted', 'closed'
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_lead_status` (`status`),
  INDEX `idx_lead_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 5. System Settings
CREATE TABLE IF NOT EXISTS `settings` (
  `key_name` VARCHAR(100) PRIMARY KEY,
  `key_value` LONGTEXT,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

